UPDATE statute_of_limitations SET years = -1, notes = 'First-degree criminal sexual conduct can be charged at any time. Second- and third-degree criminal sexual conduct has 15 years or until the victim''s 42nd birthday, whichever is later, running from DNA identification if applicable. (Mich. Comp. Laws § 767.24(1)(a), (4))', source_url = 'https://law.justia.com/codes/michigan/chapters-760-777/statute-act-175-of-1927/division-175-1927-vii/section-767-24/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 74 AND state = 'MI';
UPDATE statute_of_limitations SET years = -1, notes = 'First- through fourth-degree criminal sexual conduct can be charged at any time, whatever the victim''s age. (Minn. Stat. § 628.26(e))', source_url = 'https://law.justia.com/codes/minnesota/chapters-625-634/chapter-628/section-628-26/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 75 AND state = 'MN';
UPDATE statute_of_limitations SET years = -1, notes = 'Rape can be charged at any time, as can sexual battery of a child. Sexual battery of an adult has no limit only if DNA testing later identifies the accused; otherwise 2 years. (Miss. Code Ann. § 99-1-5(1)-(2))', source_url = 'https://law.justia.com/codes/mississippi/title-99/chapter-1/section-99-1-5/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 76 AND state = 'MS';
UPDATE statute_of_limitations SET years = -1, notes = 'First-degree rape and forcible rape (and attempts) can be charged at any time, whatever the victim''s age. (Mo. Rev. Stat. § 556.036.1)', source_url = 'https://law.justia.com/codes/missouri/title-xxxviii/chapter-556/section-556-036/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 77 AND state = 'MO';
UPDATE statute_of_limitations SET years = 10, notes = 'Sexual intercourse without consent and sexual assault of an adult must be charged within 10 years, or within 1 year after DNA testing identifies the suspect. If the victim was under 18, they can be charged at any time. (Mont. Code Ann. § 45-1-205(1)(b)-(c), (9))', source_url = 'https://law.justia.com/codes/montana/title-45/chapter-1/part-2/section-45-1-205/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 78 AND state = 'MT';
UPDATE statute_of_limitations SET years = 5, notes = 'Most felonies must be charged within 5 years. Exceptions: no limit for capital offenses, felonies involving violence, serious injury or death, sex offenses against victims under 16, arson, forgery, counterfeiting and drug trafficking. (Ala. Code §§ 15-3-1, 15-3-5)', source_url = 'https://law.justia.com/codes/alabama/title-15/chapter-3/section-15-3-1/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 103 AND state = 'AL';
UPDATE statute_of_limitations SET years = 5, notes = 'Most felonies must be charged within 5 years. Exceptions: no limit for murder, kidnapping, felony sexual abuse of a minor and serious sexual assault; 10 years for felony manslaughter, assault, stalking and certain other crimes against the person. (Alaska Stat. § 12.10.010(b))', source_url = 'https://law.justia.com/codes/alaska/title-12/chapter-10/section-12-10-010/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 104 AND state = 'AK';
UPDATE statute_of_limitations SET years = 7, notes = 'Class 2 through 6 felonies must be charged within 7 years after the offense is discovered (or should have been). No limit for homicide, violent sexual assault, class 2 sex offenses, misuse of public money and certain other crimes. (Ariz. Rev. Stat. § 13-107(A)-(B))', source_url = 'https://law.justia.com/codes/arizona/title-13/section-13-107/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 105 AND state = 'AZ';
UPDATE statute_of_limitations SET years = 3, notes = 'Class B, C, D and unclassified felonies must be charged within 3 years; Class Y and Class A felonies within 6 years. No limit for capital murder, first- and second-degree murder and listed sex offenses against minors. (Ark. Code Ann. § 5-1-109(b))', source_url = 'https://law.justia.com/codes/arkansas/title-5/subtitle-1/chapter-1/section-5-1-109', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 106 AND state = 'AR';
UPDATE statute_of_limitations SET years = 3, notes = 'Most felonies must be charged within 3 years. Exceptions: 6 years for felonies punishable by 8 or more years in prison, and no limit for crimes punishable by death or life and for many felony sex offenses. (Cal. Penal Code §§ 799, 800, 801)', source_url = 'https://justia.com/criminal/procedure/criminal-statutes-of-limitations-50-state-survey', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 107 AND state = 'CA';
UPDATE statute_of_limitations SET years = 3, notes = 'Most felonies must be charged within 3 years. No limit for murder, kidnapping, treason, sex offenses against children and forgery; 20 years for felony sexual assault of an adult. (Colo. Rev. Stat. § 16-5-401(1)(a), (8)(a.7))', source_url = 'https://law.justia.com/codes/colorado/title-16/code-of-criminal-procedure/article-5/part-4/section-16-5-401/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 108 AND state = 'CO';
UPDATE statute_of_limitations SET years = 5, notes = 'Offenses punishable by more than one year in prison must be charged within 5 years. No limit for class A felonies and sex offenses against minors; 20 years for most felony sexual assaults of adults. (Conn. Gen. Stat. § 54-193(a)-(c))', source_url = 'https://law.justia.com/codes/connecticut/title-54/chapter-966/section-54-193/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 109 AND state = 'CT';
UPDATE statute_of_limitations SET years = 5, notes = 'Most felonies must be charged within 5 years. No limit for murder and any class A felony (and sex offenses against minors); a lapsed case can still be brought within 10 years if based on DNA testing. (Del. Code Ann. tit. 11, § 205(a), (b)(1), (e), (i))', source_url = 'https://law.justia.com/codes/delaware/title-11/chapter-2/section-205/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 110 AND state = 'DE';
UPDATE statute_of_limitations SET years = 6, notes = 'Most felonies must be charged within 6 years. No limit for murder and for first- through fourth-degree sexual abuse, child sexual abuse and incest; 10 years for certain trafficking and child-exploitation crimes. (D.C. Code § 23-113(a))', source_url = 'https://law.justia.com/codes/district-of-columbia/title-23/chapter-1/section-23-113/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 111 AND state = 'DC';
UPDATE statute_of_limitations SET years = 3, notes = 'Second- and third-degree felonies must be charged within 3 years and first-degree felonies within 4 years. No limit for capital felonies, life felonies and felonies that caused a death. (Fla. Stat. § 775.15(1)-(2))', source_url = 'https://law.justia.com/codes/florida/title-xlvi/chapter-775/section-775-15/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 112 AND state = 'FL';
UPDATE statute_of_limitations SET years = 4, notes = 'Most felonies must be charged within 4 years (7 years if the victim was under 18). Other crimes punishable by death or life have 7 years, forcible rape 15 years, and murder has no limit. (O.C.G.A. § 17-3-1(b)-(c))', source_url = 'https://law.justia.com/codes/georgia/title-17/chapter-3/section-17-3-1/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 113 AND state = 'GA';
UPDATE statute_of_limitations SET years = 3, notes = 'Class B and C felonies must be charged within 3 years and class A felonies within 6 years. No limit for murder, attempted murder and first- and second-degree sexual assault. (Haw. Rev. Stat. § 701-108(2))', source_url = 'https://law.justia.com/codes/hawaii/title-37/chapter-701/section-701-108/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 114 AND state = 'HI';
UPDATE statute_of_limitations SET years = 5, notes = 'Most felonies must be charged within 5 years. No limit for murder, voluntary manslaughter, most forcible rape, sexual abuse or lewd conduct with a child, and terrorism. (Idaho Code §§ 19-401, 19-402)', source_url = 'https://law.justia.com/codes/idaho/title-19/chapter-4/section-19-402/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 115 AND state = 'ID';
UPDATE statute_of_limitations SET years = 3, notes = 'Most felonies must be charged within 3 years. No limit for murder, manslaughter, reckless homicide, arson, forgery, fatal DUI and offenses involving sexual conduct or penetration; Section 3-6 extends other crimes. (720 ILCS 5/3-5(b), 5/3-6)', source_url = 'https://law.justia.com/codes/illinois/chapter-720/act-720-ilcs-5/title-i/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 116 AND state = 'IL';
UPDATE statute_of_limitations SET years = 5, notes = 'Level 3 to Level 6 felonies must be charged within 5 years. Level 1 and Level 2 felonies and murder can be charged at any time. (Ind. Code § 35-41-4-2(a), (c), (d))', source_url = 'https://law.justia.com/codes/indiana/title-35/article-41/chapter-4/section-35-41-4-2/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 117 AND state = 'IN';
UPDATE statute_of_limitations SET years = 3, notes = 'Most felonies must be charged within 3 years. Exceptions: no limit for murder and for serious sexual abuse of a minor; 10 years for other first- to third-degree sexual abuse; other special periods for kidnapping, trafficking and robbery. (Iowa Code § 802.3)', source_url = 'https://law.justia.com/codes/iowa/title-xvi/chapter-802/section-802-3/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 118 AND state = 'IA';
UPDATE statute_of_limitations SET years = 5, notes = 'Most crimes must be charged within 5 years. No limit for murder, rape, aggravated criminal sodomy and terrorism; 10 years (or 1 year after DNA identification) for other sexually violent crimes. (Kan. Stat. Ann. § 21-5107(a), (c), (d))', source_url = 'https://law.justia.com/codes/kansas/chapter-21/article-51/section-21-5107/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 119 AND state = 'KS';
UPDATE statute_of_limitations SET years = -1, notes = 'Kentucky has no time limit for any felony unless a statute expressly provides one. (Ky. Rev. Stat. § 500.050)', source_url = 'https://law.justia.com/codes/kentucky/chapter-500/section-500-050/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 120 AND state = 'KY';
UPDATE statute_of_limitations SET years = 6, notes = 'Felonies necessarily punishable at hard labor must be charged within 6 years; other felonies within 4 years. No limit for crimes punishable by death or life, second-degree rape and molestation of a juvenile. (La. Code Crim. Proc. arts. 571, 572(A))', source_url = 'https://law.justia.com/codes/louisiana/code-of-criminal-procedure/article-572/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 121 AND state = 'LA';
UPDATE statute_of_limitations SET years = 6, notes = 'Maine uses crime classes instead of ''felony''; Class A, B and C crimes must be charged within 6 years. No limit for murder and for sex crimes against minors; 20 years for Class A-C gross sexual assault and unlawful sexual contact. (Me. Rev. Stat. tit. 17-A, § 8(1), (2), (2-A))', source_url = 'https://law.justia.com/codes/maine/title-17-a/part-1/chapter-1/section-8/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 122 AND state = 'ME';
UPDATE statute_of_limitations SET years = -1, notes = 'Maryland has no time limit for felonies. The 1-year limit and its listed exceptions apply only to misdemeanors. (Md. Code, Cts. & Jud. Proc. § 5-106)', source_url = 'https://law.justia.com/codes/maryland/courts-and-judicial-proceedings/title-5/subtitle-1/section-5-106/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 123 AND state = 'MD';
UPDATE statute_of_limitations SET years = 6, notes = 'Most crimes must be charged within 6 years. Exceptions: no limit for murder and listed sex crimes against children; 15 years for rape; 10 years for armed robbery and certain other crimes. (Mass. Gen. Laws ch. 277, § 63)', source_url = 'https://law.justia.com/codes/massachusetts/part-iv/title-ii/chapter-277/section-63/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 124 AND state = 'MA';
UPDATE statute_of_limitations SET years = 6, notes = 'Most crimes must be charged within 6 years. No limit for murder and first-degree criminal sexual conduct; longer periods for second- and third-degree criminal sexual conduct and other listed crimes. (Mich. Comp. Laws § 767.24(1), (10))', source_url = 'https://law.justia.com/codes/michigan/chapters-760-777/statute-act-175-of-1927/division-175-1927-vii/section-767-24/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 125 AND state = 'MI';
UPDATE statute_of_limitations SET years = 3, notes = 'Most crimes must be charged within 3 years. No limit for crimes causing death and first- to fourth-degree criminal sexual conduct; longer periods apply to some financial crimes, arson and trafficking. (Minn. Stat. § 628.26(l))', source_url = 'https://law.justia.com/codes/minnesota/chapters-625-634/chapter-628/section-628-26/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 126 AND state = 'MN';
UPDATE statute_of_limitations SET years = 2, notes = 'Felonies not on the no-limit list must be charged within 2 years. The no-limit list is long: murder, manslaughter, aggravated assault, kidnapping, arson, burglary, robbery, rape, larceny, embezzlement and more. (Miss. Code Ann. § 99-1-5)', source_url = 'https://law.justia.com/codes/mississippi/title-99/chapter-1/section-99-1-5/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 127 AND state = 'MS';
UPDATE statute_of_limitations SET years = 3, notes = 'Most felonies must be charged within 3 years. No limit for murder, first-degree and forcible rape and sodomy, and any class A felony; 5 years for certain arson crimes. (Mo. Rev. Stat. § 556.036.1-.2)', source_url = 'https://law.justia.com/codes/missouri/title-xxxviii/chapter-556/section-556-036/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 128 AND state = 'MO';
UPDATE statute_of_limitations SET years = 5, notes = 'Most felonies must be charged within 5 years. No limit for deliberate, mitigated and negligent homicide; 10 years for listed sex crimes (no limit if the victim was under 18). (Mont. Code Ann. § 45-1-205(1), (2)(a))', source_url = 'https://law.justia.com/codes/montana/title-45/chapter-1/part-2/section-45-1-205/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 129 AND state = 'MT';
UPDATE statute_of_limitations SET years = 1, notes = 'Misdemeanors must be charged within 12 months. (Ala. Code § 15-3-2)', source_url = 'https://law.justia.com/codes/alabama/title-15/chapter-3/section-15-3-2/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 154 AND state = 'AL';
UPDATE statute_of_limitations SET years = 5, notes = 'Misdemeanors must be charged within 5 years, the same period as most felonies. (Alaska Stat. § 12.10.010(b)(2))', source_url = 'https://law.justia.com/codes/alaska/title-12/chapter-10/section-12-10-010/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 155 AND state = 'AK';
UPDATE statute_of_limitations SET years = 1, notes = 'Misdemeanors must be charged within 1 year after discovery; petty offenses within 6 months. DUI has its own 2-year period. (Ariz. Rev. Stat. § 13-107(B))', source_url = 'https://law.justia.com/codes/arizona/title-13/section-13-107/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 156 AND state = 'AZ';
UPDATE statute_of_limitations SET years = 1, notes = 'Misdemeanors and violations must be charged within 1 year. (Ark. Code Ann. § 5-1-109(b)(3)(A))', source_url = 'https://law.justia.com/codes/arkansas/title-5/subtitle-1/chapter-1/section-5-1-109', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 157 AND state = 'AR';
UPDATE statute_of_limitations SET years = 1, notes = 'Most misdemeanors must be charged within 1 year; some listed misdemeanors have longer periods. (Cal. Penal Code § 802(a))', source_url = 'https://justia.com/criminal/procedure/criminal-statutes-of-limitations-50-state-survey', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 158 AND state = 'CA';
UPDATE statute_of_limitations SET years = 1.5, notes = 'Misdemeanors must be charged within 18 months; class 1 and 2 misdemeanor traffic offenses within 1 year, petty offenses within 6 months. (Colo. Rev. Stat. § 16-5-401(1)(a))', source_url = 'https://law.justia.com/codes/colorado/title-16/code-of-criminal-procedure/article-5/part-4/section-16-5-401/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 159 AND state = 'CO';
UPDATE statute_of_limitations SET years = 1, notes = 'Offenses punishable by one year or less must be charged within 1 year. (Conn. Gen. Stat. § 54-193(d))', source_url = 'https://law.justia.com/codes/connecticut/title-54/chapter-966/section-54-193/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 160 AND state = 'CT';
UPDATE statute_of_limitations SET years = 2, notes = 'Class B, class C and unclassified misdemeanors must be charged within 2 years; class A misdemeanors within 3 years. (Del. Code Ann. tit. 11, § 205(b)(2)-(3))', source_url = 'https://law.justia.com/codes/delaware/title-11/chapter-2/section-205/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 161 AND state = 'DE';
UPDATE statute_of_limitations SET years = 3, notes = 'Non-felony offenses must be charged within 3 years. (D.C. Code § 23-113(a)(5))', source_url = 'https://law.justia.com/codes/district-of-columbia/title-23/chapter-1/section-23-113/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 162 AND state = 'DC';
UPDATE statute_of_limitations SET years = 2, notes = 'First-degree misdemeanors must be charged within 2 years; second-degree misdemeanors within 1 year. (Fla. Stat. § 775.15(2)(c)-(d))', source_url = 'https://law.justia.com/codes/florida/title-xlvi/chapter-775/section-775-15/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 163 AND state = 'FL';
UPDATE statute_of_limitations SET years = 2, notes = 'Misdemeanors must be charged within 2 years. (O.C.G.A. § 17-3-1(e))', source_url = 'https://law.justia.com/codes/georgia/title-17/chapter-3/section-17-3-1/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 164 AND state = 'GA';
UPDATE statute_of_limitations SET years = 2, notes = 'Misdemeanors must be charged within 2 years; petty misdemeanors and violations within 1 year. (Haw. Rev. Stat. § 701-108(2)(e)-(f))', source_url = 'https://law.justia.com/codes/hawaii/title-37/chapter-701/section-701-108/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 165 AND state = 'HI';
UPDATE statute_of_limitations SET years = 1, notes = 'Misdemeanors must be charged within 1 year. (Idaho Code § 19-403(1))', source_url = 'https://law.justia.com/codes/idaho/title-19/chapter-4/section-19-403/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 166 AND state = 'ID';
UPDATE statute_of_limitations SET years = 1.5, notes = 'Misdemeanors must be charged within 18 months unless the statute for the offense says otherwise. (720 ILCS 5/3-5(b))', source_url = 'https://law.justia.com/codes/illinois/chapter-720/act-720-ilcs-5/title-i/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 167 AND state = 'IL';
UPDATE statute_of_limitations SET years = 2, notes = 'Misdemeanors must be charged within 2 years. (Ind. Code § 35-41-4-2(a))', source_url = 'https://law.justia.com/codes/indiana/title-35/article-41/chapter-4/section-35-41-4-2/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 168 AND state = 'IN';
UPDATE statute_of_limitations SET years = 3, notes = 'Aggravated and serious misdemeanors must be charged within 3 years; simple misdemeanors within 1 year. (Iowa Code §§ 802.3, 802.4)', source_url = 'https://law.justia.com/codes/iowa/title-xvi/chapter-802/section-802-3/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 169 AND state = 'IA';
UPDATE statute_of_limitations SET years = 5, notes = 'Kansas uses one 5-year period for most crimes, misdemeanors included. (Kan. Stat. Ann. § 21-5107(d))', source_url = 'https://law.justia.com/codes/kansas/chapter-21/article-51/section-21-5107/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 170 AND state = 'KS';
