UPDATE statute_of_limitations SET years = 20, notes = 'Sexual assault must be charged within 20 years. There is no limit if the victim files a written police report within that period or if DNA identifies the attacker; child sexual abuse can be charged until the victim is 36, or 43 if discovered later. (Nev. Rev. Stat. §§ 171.082, 171.083, 171.085(2), 171.095(1)(b))', source_url = 'https://law.justia.com/codes/nevada/chapter-171/statute-171-085/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 80 AND state = 'NV';
UPDATE statute_of_limitations SET years = 6, notes = 'Felony sexual assault against an adult must be charged within 6 years. If the victim was under 18, it can be charged until 22 years after the victim''s 18th birthday (age 40). (N.H. Rev. Stat. Ann. § 625:8, I, III(d))', source_url = 'https://law.justia.com/codes/new-hampshire/title-lxii/chapter-625/section-625-8/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 81 AND state = 'NH';
UPDATE statute_of_limitations SET years = -1, notes = 'No time limit for sexual assault or aggravated sexual assault (N.J.S.A. 2C:14-2). For criminal sexual contact or child endangerment against a victim under 18, the limit is 5 years after the victim turns 18 or 2 years after the victim discovers the offense, whichever is later. (N.J. Stat. Ann. § 2C:1-6(a)(1), (b)(4))', source_url = 'https://law.justia.com/codes/new-jersey/title-2c/section-2c-1-6', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 82 AND state = 'NJ';
UPDATE statute_of_limitations SET years = -1, notes = 'No time limit for first-degree rape. Second-degree rape has 20 years and third-degree rape has 10 years. For victims under 18, the clock for most sex offenses starts at age 23 or at the first report to police, if earlier. (N.Y. Crim. Proc. Law § 30.10(2)(a)-(a-2), (3)(f))', source_url = 'https://www.nysenate.gov/legislation/laws/CPL/30.10', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 84 AND state = 'NY';
UPDATE statute_of_limitations SET years = -1, notes = 'No time limit for rape or other felony sex offenses, because North Carolina has no felony statute of limitations. The same applies when the victim is a child. (N.C. Gen. Stat. § 15-1)', source_url = 'https://ncleg.gov/EnactedLegislation/Statutes/HTML/BySection/Chapter_15/GS_15-1.html', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 85 AND state = 'NC';
UPDATE statute_of_limitations SET years = 7, notes = 'Felony sex offenses must be charged within 7 years. If the victim was under 18, listed offenses can be charged within 21 years, or within 3 years after a late report or DNA identification. For victims under 15, the clock starts at age 15. (N.D. Cent. Code §§ 29-04-02.1, 29-04-03.1, 29-04-03.2)', source_url = 'https://law.justia.com/codes/north-dakota/title-29/chapter-29-04/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 86 AND state = 'ND';
UPDATE statute_of_limitations SET years = 25, notes = 'Rape and sexual battery must be charged within 25 years. If the victim was a child, the clock starts when the victim turns 18, and a DNA match can open a new 5-year window. (Ohio Rev. Code § 2901.13(A)(4), (D), (J))', source_url = 'https://codes.ohio.gov/orc/2901.13', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 87 AND state = 'OH';
UPDATE statute_of_limitations SET years = 12, notes = 'Rape and forcible sodomy against an adult must be charged within 12 years after the crime is reported to police. Against a child, they can be charged until the victim''s 45th birthday. If preserved DNA later identifies the suspect, charges can be filed within 3 years of that match. (Okla. Stat. tit. 22, § 152(C))', source_url = 'https://law.justia.com/codes/oklahoma/2023/title-22/section-22-152/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 88 AND state = 'OK';
UPDATE statute_of_limitations SET years = 20, notes = 'First-degree rape, sodomy, unlawful sexual penetration and sexual abuse must be charged within 20 years, or before a child victim turns 30 if that is later. Second-degree rape and other listed sex felonies have 6 years, or until a child victim turns 30, or 12 years after a report, whichever comes first. (Or. Rev. Stat. § 131.125(2)-(3))', source_url = 'https://law.justia.com/codes/oregon/volume-04/chapter-131/section-131-125/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 89 AND state = 'OR';
UPDATE statute_of_limitations SET years = 12, notes = 'Rape and sexual assault of an adult must be charged within 12 years. There is no time limit for rape or sexual assault of a victim under 18, and other sex offenses against a minor can be charged until the victim turns 55. (42 Pa. Cons. Stat. §§ 5551(7), 5552(b.1), (c)(3))', source_url = 'https://law.justia.com/codes/pennsylvania/title-42/chapter-55/section-5552/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 90 AND state = 'PA';
UPDATE statute_of_limitations SET years = -1, notes = 'No time limit for rape, first-degree sexual assault, or first- and second-degree child molestation. (R.I. Gen. Laws § 12-12-17(a))', source_url = 'https://law.justia.com/codes/rhode-island/title-12/chapter-12-12/section-12-12-17/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 91 AND state = 'RI';
UPDATE statute_of_limitations SET years = -1, notes = 'No time limit for rape or aggravated rape of an adult committed on or after July 1, 2014, if the victim reports it to police within 3 years; otherwise the class-based felony limits apply. For victims under 13 there is no limit, and for victims 13-17 there is no limit for listed offenses, but older cases need corroborating evidence. (Tenn. Code Ann. § 40-2-101(l), (q))', source_url = 'https://law.justia.com/codes/tennessee/title-40/chapter-2/section-40-2-101/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 94 AND state = 'TN';
UPDATE statute_of_limitations SET years = 10, notes = 'Adult sexual assault must be charged within 10 years. There is no limit if DNA evidence is untested or matches an unidentified person, if the accused is believed to have assaulted 5 or more victims, or if the victim was a child. (Tex. Code Crim. Proc. art. 12.01(1)(B)-(C), (2)(E))', source_url = 'https://law.justia.com/codes/texas/code-of-criminal-procedure/title-1/chapter-12/article-12-01/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 95 AND state = 'TX';
UPDATE statute_of_limitations SET years = -1, notes = 'No time limit, because rape and other felony sex offenses are felonies and Virginia has no felony statute of limitations. The same applies when the victim is a child. (Va. Code Ann. § 19.2-8)', source_url = 'https://law.justia.com/codes/virginia/title-19-2/chapter-1/section-19-2-8/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 98 AND state = 'VA';
UPDATE statute_of_limitations SET years = 20, notes = 'First- and second-degree rape must be charged within 20 years, and third-degree rape within 10 years. There is no limit if the victim was under 16, and no limit for rape of a child or child molestation. (Wash. Rev. Code § 9A.04.080(1)(a)-(c))', source_url = 'https://law.justia.com/codes/washington/title-9a/chapter-9a-04/section-9a-04-080/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 99 AND state = 'WA';
UPDATE statute_of_limitations SET years = -1, notes = 'No time limit, because sexual assault is a felony and West Virginia has no felony statute of limitations. The same applies when the victim is a child. (W. Va. Code § 61-11-9)', source_url = 'https://code.wvlegislature.gov/61-11-9/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 100 AND state = 'WV';
UPDATE statute_of_limitations SET years = -1, notes = 'No time limit for first-degree sexual assault or first-degree sexual assault of a child. Second-degree sexual assault has 10 years, and other listed child sex offenses can be charged until the victim turns 45. (Wis. Stat. § 939.74(2)(a), (2)(ar), (2)(c))', source_url = 'https://law.justia.com/codes/wisconsin/chapter-939/section-939-74/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 101 AND state = 'WI';
UPDATE statute_of_limitations SET years = 3, notes = 'Most felonies must be charged within 3 years. Murder, treason, arson, forgery, and first- or second-degree sexual assault have no limit; some fraud and vulnerable-adult offenses have 5-6 years. (Neb. Rev. Stat. § 29-110(1), (11))', source_url = 'https://law.justia.com/codes/nebraska/chapter-29/statute-29-110/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 130 AND state = 'NE';
UPDATE statute_of_limitations SET years = 3, notes = 'Most felonies must be charged within 3 years. Theft, robbery, burglary, forgery and arson have 4 years, sexual assault has 20 years, and murder has no limit. (Nev. Rev. Stat. § 171.085)', source_url = 'https://law.justia.com/codes/nevada/chapter-171/statute-171-085/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 131 AND state = 'NV';
UPDATE statute_of_limitations SET years = 6, notes = 'Class A and class B felonies must be charged within 6 years. Murder has no limit, and sex offenses against children can be charged until 22 years after the victim''s 18th birthday. (N.H. Rev. Stat. Ann. § 625:8, I-III)', source_url = 'https://law.justia.com/codes/new-hampshire/title-lxii/chapter-625/section-625-8/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 132 AND state = 'NH';
UPDATE statute_of_limitations SET years = 5, notes = 'Indictable crimes must be charged within 5 years. Murder, manslaughter, aggravated sexual assault and sexual assault have no limit. (N.J. Stat. Ann. § 2C:1-6(a)-(b))', source_url = 'https://law.justia.com/codes/new-jersey/title-2c/section-2c-1-6', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 133 AND state = 'NJ';
UPDATE statute_of_limitations SET years = 5, notes = 'Third- and fourth-degree felonies must be charged within 5 years and second-degree felonies within 6 years. Capital felonies, first-degree violent felonies and second-degree murder have no limit. (N.M. Stat. Ann. § 30-1-8)', source_url = 'https://law.justia.com/codes/new-mexico/chapter-30/article-1/section-30-1-8/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 134 AND state = 'NM';
UPDATE statute_of_limitations SET years = 5, notes = 'Most felonies must be charged within 5 years. Class A felonies and first-degree rape have no limit, and some sex offenses have 10 or 20 years. (N.Y. Crim. Proc. Law § 30.10(2))', source_url = 'https://www.nysenate.gov/legislation/laws/CPL/30.10', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 135 AND state = 'NY';
UPDATE statute_of_limitations SET years = -1, notes = 'North Carolina has no time limit for felonies; charges may be brought at any time. Only misdemeanors have a limit (G.S. 15-1). (N.C. Gen. Stat. § 15-1)', source_url = 'https://ncleg.gov/EnactedLegislation/Statutes/HTML/BySection/Chapter_15/GS_15-1.html', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 136 AND state = 'NC';
UPDATE statute_of_limitations SET years = 3, notes = 'Most felonies must be charged within 3 years. Felony sex offenses and human trafficking have 7 years, sexual abuse of a minor has 21 years, and murder has no limit. (N.D. Cent. Code §§ 29-04-02, 29-04-02.1, 29-04-03.1)', source_url = 'https://law.justia.com/codes/north-dakota/title-29/chapter-29-04/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 137 AND state = 'ND';
UPDATE statute_of_limitations SET years = 6, notes = 'Most felonies must be charged within 6 years. Murder has no limit; rape and sexual battery have 25 years; voluntary manslaughter, kidnapping and some other serious offenses have 20 years. (Ohio Rev. Code § 2901.13(A))', source_url = 'https://codes.ohio.gov/orc/2901.13', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 138 AND state = 'OH';
UPDATE statute_of_limitations SET years = 3, notes = 'Most crimes, including most felonies, must be charged within 3 years. Murder has no limit; manslaughter has 10 years after it is reported; embezzlement and bribery have 7 years after discovery; rape has 12 years after it is reported. (Okla. Stat. tit. 22, §§ 151, 152(H))', source_url = 'https://law.justia.com/codes/oklahoma/2023/title-22/section-22-152/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 139 AND state = 'OK';
UPDATE statute_of_limitations SET years = 3, notes = 'Most felonies must be charged within 3 years. Murder and manslaughter have no limit, first-degree rape and other listed sex felonies have 20 years, and arson has 6 years. (Or. Rev. Stat. § 131.125(8)(a))', source_url = 'https://law.justia.com/codes/oregon/volume-04/chapter-131/section-131-125/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 140 AND state = 'OR';
UPDATE statute_of_limitations SET years = 5, notes = 'Pennsylvania has no single felony period: listed ''major offenses'' (most serious felonies) have 5 years, offenses not listed have 2 years, major sexual offenses have 12 years, and murder has no limit. (42 Pa. Cons. Stat. §§ 5551, 5552(a)-(b.1))', source_url = 'https://law.justia.com/codes/pennsylvania/title-42/chapter-55/section-5552/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 141 AND state = 'PA';
UPDATE statute_of_limitations SET years = 3, notes = 'Offenses not specifically listed must be charged within 3 years. Many serious felonies (homicide, rape, robbery, burglary, arson, drug distribution, life-sentence offenses) have no limit, and felony larceny, bribery, perjury and fraud offenses have 10 years. (R.I. Gen. Laws § 12-12-17)', source_url = 'https://law.justia.com/codes/rhode-island/title-12/chapter-12-12/section-12-12-17/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 142 AND state = 'RI';
UPDATE statute_of_limitations SET years = 4, notes = 'Tennessee sets limits by felony class: Class A 15 years, Class B 8 years, Class C and D 4 years, Class E 2 years. Offenses punishable by death or life imprisonment have no limit. (Tenn. Code Ann. § 40-2-101(a)-(b))', source_url = 'https://law.justia.com/codes/tennessee/title-40/chapter-2/section-40-2-101/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 145 AND state = 'TN';
UPDATE statute_of_limitations SET years = 3, notes = 'Felonies not otherwise listed must be charged within 3 years. Murder, manslaughter and many child sex offenses have no limit, and sexual assault and several other listed felonies have 10 years. (Tex. Code Crim. Proc. art. 12.01(11))', source_url = 'https://law.justia.com/codes/texas/code-of-criminal-procedure/title-1/chapter-12/article-12-01/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 146 AND state = 'TX';
UPDATE statute_of_limitations SET years = -1, notes = 'Virginia has no time limit for felonies. The general limitation statute (Va. Code § 19.2-8) covers misdemeanors and a few listed offenses. (Va. Code Ann. § 19.2-8)', source_url = 'https://law.justia.com/codes/virginia/title-19-2/chapter-1/section-19-2-8/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 149 AND state = 'VA';
UPDATE statute_of_limitations SET years = 3, notes = 'Felonies not otherwise listed must be charged within 3 years. Murder and many child sex offenses have no limit, and first- and second-degree rape have 20 years. (Wash. Rev. Code § 9A.04.080(1)(j))', source_url = 'https://law.justia.com/codes/washington/title-9a/chapter-9a-04/section-9a-04-080/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 150 AND state = 'WA';
UPDATE statute_of_limitations SET years = -1, notes = 'West Virginia has no time limit for felonies. Its limitation statute covers only misdemeanors (1 year) and perjury (3 years). (W. Va. Code § 61-11-9)', source_url = 'https://code.wvlegislature.gov/61-11-9/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 151 AND state = 'WV';
UPDATE statute_of_limitations SET years = 6, notes = 'Most felonies must be charged within 6 years. Homicide and first-degree sexual assault have no limit, and second-degree sexual assault has 10 years. (Wis. Stat. § 939.74(1)-(2))', source_url = 'https://law.justia.com/codes/wisconsin/chapter-939/section-939-74/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 152 AND state = 'WI';
UPDATE statute_of_limitations SET years = 1.5, notes = 'Misdemeanors must be charged within 18 months. Minor offenses punishable only by a fine up to $100 and up to 3 months in jail have 1 year. (Neb. Rev. Stat. § 29-110(2))', source_url = 'https://law.justia.com/codes/nebraska/chapter-29/statute-29-110/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 181 AND state = 'NE';
UPDATE statute_of_limitations SET years = 1, notes = 'Simple misdemeanors must be charged within 1 year; gross misdemeanors within 2 years. (Nev. Rev. Stat. § 171.090)', source_url = 'https://law.justia.com/codes/nevada/2024/chapter-171/statute-171-090/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 182 AND state = 'NV';
UPDATE statute_of_limitations SET years = 1, notes = 'Misdemeanors must be charged within 1 year; violations within 3 months. (N.H. Rev. Stat. Ann. § 625:8, I(c)-(d))', source_url = 'https://law.justia.com/codes/new-hampshire/title-lxii/chapter-625/section-625-8/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 183 AND state = 'NH';
UPDATE statute_of_limitations SET years = 1, notes = 'Disorderly persons and petty disorderly persons offenses (New Jersey''s misdemeanor-level offenses) must be charged within 1 year. (N.J. Stat. Ann. § 2C:1-6(b)(2))', source_url = 'https://law.justia.com/codes/new-jersey/title-2c/section-2c-1-6', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 184 AND state = 'NJ';
UPDATE statute_of_limitations SET years = 2, notes = 'Misdemeanors must be charged within 2 years; petty misdemeanors within 1 year. (N.M. Stat. Ann. § 30-1-8(C)-(D))', source_url = 'https://law.justia.com/codes/new-mexico/chapter-30/article-1/section-30-1-8/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 185 AND state = 'NM';
UPDATE statute_of_limitations SET years = 2, notes = 'Misdemeanors must be charged within 2 years; petty offenses within 1 year. (N.Y. Crim. Proc. Law § 30.10(2)(c)-(d))', source_url = 'https://www.nysenate.gov/legislation/laws/CPL/30.10', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 186 AND state = 'NY';
UPDATE statute_of_limitations SET years = 2, notes = 'Most misdemeanors must be charged within 2 years. A few listed misdemeanors, including failure to report child abuse and misdemeanor child abuse, have 10 years. (N.C. Gen. Stat. § 15-1(a)-(b))', source_url = 'https://ncleg.gov/EnactedLegislation/Statutes/HTML/BySection/Chapter_15/GS_15-1.html', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 187 AND state = 'NC';
UPDATE statute_of_limitations SET years = 2, notes = 'Misdemeanors and infractions must be charged within 2 years. (N.D. Cent. Code § 29-04-03)', source_url = 'https://law.justia.com/codes/north-dakota/title-29/chapter-29-04/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 188 AND state = 'ND';
UPDATE statute_of_limitations SET years = 2, notes = 'Misdemeanors must be charged within 2 years; minor misdemeanors within 6 months. (Ohio Rev. Code § 2901.13(A)(1)(b)-(c))', source_url = 'https://codes.ohio.gov/orc/2901.13', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 189 AND state = 'OH';
UPDATE statute_of_limitations SET years = 3, notes = 'Oklahoma''s catch-all rule gives 3 years for all offenses not otherwise listed, including misdemeanors. (Okla. Stat. tit. 22, § 152(H))', source_url = 'https://law.justia.com/codes/oklahoma/2023/title-22/section-22-152/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 190 AND state = 'OK';
UPDATE statute_of_limitations SET years = 2, notes = 'Misdemeanors must be charged within 2 years; violations within 6 months. Some listed sex-related misdemeanors have 4 years. (Or. Rev. Stat. § 131.125(4), (8)(b)-(c))', source_url = 'https://law.justia.com/codes/oregon/volume-04/chapter-131/section-131-125/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 191 AND state = 'OR';
UPDATE statute_of_limitations SET years = 2, notes = 'Most offenses, including most misdemeanors, must be charged within 2 years. Misdemeanors on the ''major offenses'' list have 5 years. (42 Pa. Cons. Stat. § 5552(a)-(b))', source_url = 'https://law.justia.com/codes/pennsylvania/title-42/chapter-55/section-5552/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 192 AND state = 'PA';
UPDATE statute_of_limitations SET years = 3, notes = 'Offenses not specifically listed, including misdemeanors, must be charged within 3 years. (R.I. Gen. Laws § 12-12-17(c))', source_url = 'https://law.justia.com/codes/rhode-island/title-12/chapter-12-12/section-12-12-17/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 193 AND state = 'RI';
UPDATE statute_of_limitations SET years = 1, notes = 'Misdemeanors must be charged within 12 months; gaming offenses within 6 months. (Tenn. Code Ann. § 40-2-102(a))', source_url = 'https://law.justia.com/codes/tennessee/title-40/chapter-2/section-40-2-102/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 196 AND state = 'TN';
UPDATE statute_of_limitations SET years = 1, notes = 'Misdemeanors must be charged within 1 year. Petit larceny has 5 years. (Va. Code Ann. § 19.2-8)', source_url = 'https://law.justia.com/codes/virginia/title-19-2/chapter-1/section-19-2-8/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 200 AND state = 'VA';
UPDATE statute_of_limitations SET years = 2, notes = 'Gross misdemeanors must be charged within 2 years; simple misdemeanors within 1 year. (Wash. Rev. Code § 9A.04.080(1)(k)-(l))', source_url = 'https://law.justia.com/codes/washington/title-9a/chapter-9a-04/section-9a-04-080/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 201 AND state = 'WA';
UPDATE statute_of_limitations SET years = 1, notes = 'Misdemeanors must be charged within 1 year. (W. Va. Code § 61-11-9)', source_url = 'https://code.wvlegislature.gov/61-11-9/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 202 AND state = 'WV';
UPDATE statute_of_limitations SET years = 3, notes = 'Misdemeanors must be charged within 3 years. (Wis. Stat. § 939.74(1))', source_url = 'https://law.justia.com/codes/wisconsin/chapter-939/section-939-74/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 203 AND state = 'WI';
UPDATE statute_of_limitations SET years = 1, notes = 'A DUI that is a misdemeanor must be charged within 12 months. A fourth or later DUI is a Class E felony with 2 years. (Tenn. Code Ann. §§ 40-2-101(b)(4), 40-2-102(a))', source_url = 'https://law.justia.com/codes/tennessee/title-40/chapter-2/section-40-2-102/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 208 AND state = 'TN';
UPDATE statute_of_limitations SET years = 2, notes = 'Misdemeanor DWI must be charged within 2 years. Felony DWI has 5 years, and DWAI (a traffic infraction) has 1 year. (N.Y. Crim. Proc. Law § 30.10(2)(b)-(d))', source_url = 'https://www.nysenate.gov/legislation/laws/CPL/30.10', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 209 AND state = 'NY';
UPDATE statute_of_limitations SET years = 2, notes = 'Ordinary impaired driving is a misdemeanor and must be charged within 2 years. Felony impaired-driving charges (such as habitual DWI or DWI causing death) have no limit. (N.C. Gen. Stat. § 15-1(a))', source_url = 'https://ncleg.gov/EnactedLegislation/Statutes/HTML/BySection/Chapter_15/GS_15-1.html', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 235 AND state = 'NC';
UPDATE statute_of_limitations SET years = 2, notes = 'A first or second DUI is a misdemeanor and must be charged within 2 years. Felony DUI (fourth or later offense, or causing injury or death) has 3 years. (N.D. Cent. Code §§ 29-04-02, 29-04-03)', source_url = 'https://law.justia.com/codes/north-dakota/title-29/chapter-29-04/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 236 AND state = 'ND';
UPDATE statute_of_limitations SET years = 1.5, notes = 'Misdemeanor DUI must be charged within 18 months. Felony DUI (such as a fourth offense or DUI causing serious injury) has 3 years. (Neb. Rev. Stat. § 29-110(1)-(2))', source_url = 'https://law.justia.com/codes/nebraska/chapter-29/statute-29-110/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 237 AND state = 'NE';
UPDATE statute_of_limitations SET years = 1, notes = 'Misdemeanor DWI must be charged within 1 year. Felony aggravated DWI and repeat DWI felonies have 6 years. (N.H. Rev. Stat. Ann. § 625:8, I)', source_url = 'https://law.justia.com/codes/new-hampshire/title-lxii/chapter-625/section-625-8/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 238 AND state = 'NH';
UPDATE statute_of_limitations SET years = 3, notes = 'DWI is defined in the Motor Vehicle Code, not the Criminal Code, so the 3-year limit for crimes outside the Criminal Code applies. (N.M. Stat. Ann. § 30-1-8(H))', source_url = 'https://law.justia.com/codes/new-mexico/chapter-30/article-1/section-30-1-8/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 240 AND state = 'NM';
UPDATE statute_of_limitations SET years = 1, notes = 'A first or second DUI is a misdemeanor and must be charged within 1 year. Felony DUI (third offense, or causing death or substantial harm) has 3 years. (Nev. Rev. Stat. §§ 171.085(4), 171.090(2))', source_url = 'https://law.justia.com/codes/nevada/chapter-171/statute-171-085/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 241 AND state = 'NV';
UPDATE statute_of_limitations SET years = 2, notes = 'Misdemeanor OVI must be charged within 2 years. Felony OVI has 6 years. (Ohio Rev. Code § 2901.13(A)(1))', source_url = 'https://codes.ohio.gov/orc/2901.13', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 242 AND state = 'OH';
UPDATE statute_of_limitations SET years = 3, notes = 'DUI, whether a misdemeanor or felony, falls under the 3-year catch-all rule. (Okla. Stat. tit. 22, § 152(H))', source_url = 'https://law.justia.com/codes/oklahoma/2023/title-22/section-22-152/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 243 AND state = 'OK';
UPDATE statute_of_limitations SET years = 2, notes = 'Misdemeanor DUII must be charged within 2 years. Felony DUII has 3 years. (Or. Rev. Stat. § 131.125(8))', source_url = 'https://law.justia.com/codes/oregon/volume-04/chapter-131/section-131-125/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 244 AND state = 'OR';
UPDATE statute_of_limitations SET years = 2, notes = 'DUI must be charged within 2 years under Pennsylvania''s general rule. Leaving the scene of a crash involving death or injury has no limit. (42 Pa. Cons. Stat. §§ 5551, 5552(a))', source_url = 'https://law.justia.com/codes/pennsylvania/title-42/chapter-55/section-5552/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 245 AND state = 'PA';
UPDATE statute_of_limitations SET years = 3, notes = 'DUI falls under Rhode Island''s 3-year catch-all rule. (R.I. Gen. Laws § 12-12-17(c))', source_url = 'https://law.justia.com/codes/rhode-island/title-12/chapter-12-12/section-12-12-17/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 246 AND state = 'RI';
UPDATE statute_of_limitations SET years = 1, notes = 'Misdemeanor DUI must be charged within 1 year. Felony DUI (such as a third offense within 10 years) has no limit. (Va. Code Ann. § 19.2-8)', source_url = 'https://law.justia.com/codes/virginia/title-19-2/chapter-1/section-19-2-8/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 250 AND state = 'VA';
UPDATE statute_of_limitations SET years = 2, notes = 'DUI is a gross misdemeanor and must be charged within 2 years. Felony DUI has 3 years. (Wash. Rev. Code § 9A.04.080(1)(j)-(k))', source_url = 'https://law.justia.com/codes/washington/title-9a/chapter-9a-04/section-9a-04-080/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 252 AND state = 'WA';
UPDATE statute_of_limitations SET years = 1, notes = 'Misdemeanor DUI must be charged within 1 year. Felony DUI (third offense, or causing death or serious injury) has no limit. (W. Va. Code § 61-11-9)', source_url = 'https://code.wvlegislature.gov/61-11-9/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 254 AND state = 'WV';
UPDATE drug_penalties SET charge_level = 'State jail felony', min_days = 180, max_days = 730, min_fine = 0, max_fine = 10000, notes = 'In Texas, possessing less than 1 gram of a Penalty Group 1 or 1-B drug (such as heroin, cocaine, meth or fentanyl) is a state jail felony: 180 days to 2 years in state jail and a fine up to $10,000. (Tex. Health & Safety Code § 481.115(b); Tex. Penal Code § 12.35)', source_url = 'https://law.justia.com/codes/texas/health-and-safety-code/title-6/subtitle-c/chapter-481/subchapter-d/section-481-115', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 11 AND state = 'TX';
UPDATE drug_penalties SET charge_level = 'Third degree felony', min_days = 730, max_days = 3650, min_fine = 0, max_fine = 10000, notes = 'Possessing 1 gram to under 4 grams of a Penalty Group 1 or 1-B drug is a third-degree felony in Texas: 2 to 10 years in prison and a fine up to $10,000. (Tex. Health & Safety Code § 481.115(c); Tex. Penal Code § 12.34)', source_url = 'https://law.justia.com/codes/texas/health-and-safety-code/title-6/subtitle-c/chapter-481/subchapter-d/section-481-115', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 12 AND state = 'TX';
UPDATE drug_penalties SET charge_level = 'Second degree felony', min_days = 730, max_days = 7300, min_fine = 0, max_fine = 10000, notes = 'Possessing 4 grams to under 200 grams of a Penalty Group 1 or 1-B drug is a second-degree felony in Texas: 2 to 20 years in prison and a fine up to $10,000. (Tex. Health & Safety Code § 481.115(d); Tex. Penal Code § 12.33)', source_url = 'https://law.justia.com/codes/texas/health-and-safety-code/title-6/subtitle-c/chapter-481/subchapter-d/section-481-115', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 13 AND state = 'TX';
UPDATE drug_penalties SET charge_level = 'First degree felony', min_days = 1825, max_days = 36135, min_fine = 0, max_fine = 10000, notes = 'Possessing 200 grams to under 400 grams of a Penalty Group 1 or 1-B drug is a first-degree felony: 5 to 99 years or life and a fine up to $10,000. At 400 grams or more the range rises to 10 to 99 years or life and a fine up to $100,000. (Tex. Health & Safety Code § 481.115(e)-(f); Tex. Penal Code § 12.32)', source_url = 'https://law.justia.com/codes/texas/health-and-safety-code/title-6/subtitle-c/chapter-481/subchapter-d/section-481-115', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 14 AND state = 'TX';
UPDATE drug_penalties SET charge_level = 'Class B misdemeanor', min_days = 0, max_days = 180, min_fine = 0, max_fine = 2000, notes = 'Texas has not legalized recreational marijuana. Possessing 2 ounces or less is a Class B misdemeanor: up to 180 days in jail and a fine up to $2,000. (Tex. Health & Safety Code § 481.121(b)(1); Tex. Penal Code § 12.22)', source_url = 'https://texas.public.law/statutes/tex._health_and_safety_code_section_481.121', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 15 AND state = 'TX';
UPDATE drug_penalties SET charge_level = 'Class A misdemeanor', min_days = 0, max_days = 365, min_fine = 0, max_fine = 4000, notes = 'Possessing more than 2 ounces up to 4 ounces of marijuana in Texas is a Class A misdemeanor: up to 1 year in jail and a fine up to $4,000. (Tex. Health & Safety Code § 481.121(b)(2); Tex. Penal Code § 12.21)', source_url = 'https://texas.public.law/statutes/tex._health_and_safety_code_section_481.121', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 16 AND state = 'TX';
UPDATE drug_penalties SET charge_level = 'State jail felony', min_days = 180, max_days = 730, min_fine = 0, max_fine = 10000, notes = 'Possessing more than 4 ounces up to 5 pounds of marijuana in Texas is a state jail felony: 180 days to 2 years and a fine up to $10,000. Larger amounts are higher felonies: over 5 lb is third degree, over 50 lb second degree, over 2,000 lb first degree (5-99 years or life, up to $50,000). (Tex. Health & Safety Code § 481.121(b)(3)-(6); Tex. Penal Code § 12.35)', source_url = 'https://texas.public.law/statutes/tex._health_and_safety_code_section_481.121', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 17 AND state = 'TX';
UPDATE drug_penalties SET charge_level = 'State jail felony', min_days = 180, max_days = 730, min_fine = 0, max_fine = 10000, notes = 'Possessing less than 1 gram of methamphetamine (Penalty Group 1) in Texas is a state jail felony: 180 days to 2 years and a fine up to $10,000. (Tex. Health & Safety Code § 481.115(b); Tex. Penal Code § 12.35)', source_url = 'https://law.justia.com/codes/texas/health-and-safety-code/title-6/subtitle-c/chapter-481/subchapter-d/section-481-115', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', last_reviewed_at = '2026-10-26', updated_at = NOW() WHERE id = 18 AND state = 'TX';
UPDATE victim_compensation SET program_name = 'Alabama Crime Victims'' Compensation Commission', phone = '(800) 541-9388', url = 'https://acvcc.alabama.gov', address = 'P.O. Box 231267, Montgomery, AL 36123-1267', max_award = 15000, deadline_days = 365, covers = '["medical", "mental health", "lost wages", "funeral", "rehabilitation"]', notes = 'Pays up to $15,000 for crime-related costs not covered by insurance or other sources. Apply within 1 year of the crime and report it to police within 72 hours; late filing needs written good cause.', source_url = 'https://acvcc.alabama.gov/?p=10613', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', updated_at = NOW() WHERE id = 1 AND state = 'AL';
UPDATE victim_compensation SET program_name = 'Alaska Violent Crimes Compensation Board', phone = '(800) 764-3040', url = 'https://vccb.alaska.gov/', address = '4300 Boniface Pkwy, Anchorage, AK 99504', max_award = 40000, deadline_days = 730, covers = NULL, notes = 'Pays up to $40,000 per victim ($80,000 total when a death leaves several dependents). Apply within 2 years of the crime and report it to police within 5 days unless that was not reasonably possible.', source_url = 'https://vccb.alaska.gov/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', updated_at = NOW() WHERE id = 2 AND state = 'AK';
UPDATE victim_compensation SET program_name = 'Arizona Crime Victim Compensation Program (ACJC; applications through county attorney''s offices)', phone = NULL, url = 'https://www.azcjc.gov/Programs/Victim-Services/Compensation-Program', address = NULL, max_award = NULL, deadline_days = NULL, covers = '["medical", "funeral", "mental health", "lost wages", "transportation", "crime scene cleanup"]', notes = 'Apply through the County Attorney''s Office in the county where the crime happened; each county has its own phone number. The program pays only after insurance and other sources.', source_url = 'https://www.azcjc.gov/Programs/Victim-Services/Compensation-Program', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', updated_at = NOW() WHERE id = 3 AND state = 'AZ';
UPDATE victim_compensation SET program_name = 'Arkansas Crime Victims Reparations Board', phone = '(501) 682-1020', url = 'https://portal.arkansas.gov/state_agencies/department-of-public-safety/crime-victims-reparations-board/', address = NULL, max_award = 10000, deadline_days = 365, covers = NULL, notes = 'Pays up to $10,000, or up to $25,000 for catastrophic injury. Apply within 1 year and report the crime within 72 hours (the 72-hour rule does not apply to minors).', source_url = 'https://portal.arkansas.gov/state_agencies/department-of-public-safety/crime-victims-reparations-board/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', updated_at = NOW() WHERE id = 4 AND state = 'AR';
UPDATE victim_compensation SET program_name = 'California Victim Compensation Board (CalVCB)', phone = '(800) 777-9229', url = 'https://victims.ca.gov', address = NULL, max_award = 70000, deadline_days = 2555, covers = NULL, notes = 'Pays up to $70,000 per application. Apply within 7 years of the crime; victims who were minors have until 7 years after turning 21 (age 28), and late applications can be accepted for good cause.', source_url = 'https://victims.ca.gov/for-victims/frequently-asked-questions', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', updated_at = NOW() WHERE id = 5 AND state = 'CA';
UPDATE victim_compensation SET program_name = 'Colorado Crime Victim Compensation (run by each judicial district; overseen by DCJ Office for Victims Programs)', phone = NULL, url = 'https://dcj.colorado.gov/dcj-offices/ovp/crime-victim-compensation', address = NULL, max_award = NULL, deadline_days = NULL, covers = NULL, notes = 'Colorado has no single statewide claims office: apply to the compensation program in the judicial district where the crime happened. Limits and rules are set by each district board.', source_url = 'https://dcj.colorado.gov/dcj-offices/ovp/crime-victim-compensation', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', updated_at = NOW() WHERE id = 6 AND state = 'CO';
UPDATE victim_compensation SET program_name = 'Connecticut Judicial Branch Office of Victim Services', phone = '(888) 286-7347', url = 'https://www.jud.ct.gov/', address = NULL, max_award = 15000, deadline_days = 730, covers = NULL, notes = 'Pays up to $15,000 for personal injury and up to $25,000 to dependents of a homicide victim. Apply within 2 years of the crime; the deadline can be waived in some cases, and the crime must be reported to police.', source_url = 'https://portal.ct.gov/ova/knowledge-base/articles/victim-resources/how-to-apply-for-restitution', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', updated_at = NOW() WHERE id = 7 AND state = 'CT';
UPDATE victim_compensation SET program_name = 'Delaware Victims'' Compensation Assistance Program (VCAP), Department of Justice', phone = '(302) 255-1770', url = 'https://attorneygeneral.delaware.gov/VCAP/', address = '900 N King St, Suite 4, Wilmington, DE 19801', max_award = 25000, deadline_days = 365, covers = NULL, notes = 'Pays up to $25,000 (up to $50,000 for permanent total disability). Apply within 1 year of the crime and report it to police within 72 hours; VCAP can extend or waive these limits.', source_url = 'https://attorneygeneral.delaware.gov/VCAP/', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', updated_at = NOW() WHERE id = 8 AND state = 'DE';
UPDATE victim_compensation SET program_name = 'Crime Victims Compensation Program, D.C. Superior Court', phone = '(202) 879-4216', url = 'https://www.dccourts.gov/services/crime-victims-compensation-matters/eligibility', address = 'Court Building A, 515 5th St NW, Room 109, Washington, DC 20001', max_award = 25000, deadline_days = 365, covers = NULL, notes = 'Pays up to $25,000 per claim. Apply within 1 year of the crime (or of learning about the program) and report the crime to police within 7 days.', source_url = 'https://www.dccourts.gov/sites/default/files/matters-docs/CVCP_Brochure.pdf', verified_by = 'Source-checked 2026-10-26 (legal accuracy review; not attorney-reviewed)', updated_at = NOW() WHERE id = 9 AND state = 'DC';
